import sys
from collections import defaultdict

def find_index_to_remove(n, b):
    if n == 2:
        return 1

    diff_count = defaultdict(int)
    min_diff = float('inf')
    max_diff = float('-inf')

    for i in range(1, n):
        diff = b[i] - b[i - 1]
        diff_count[diff] += 1
        min_diff = min(min_diff, diff)
        max_diff = max(max_diff, diff)

    if len(diff_count) == 1:
        return 1

    for i in range(n):
        new_min_diff = float('inf')
        new_max_diff = float('-inf')
        for j in range(n):
            if i == j:
                continue
            if j == 0:
                diff = b[j + 1] - b[j]
            elif j == n - 1:
                diff = b[j] - b[j - 1]
            else:
                diff1 = b[j + 1] - b[j]
                diff2 = b[j] - b[j - 1]
                if diff1 != diff2:
                    break
                diff = diff1
            new_min_diff = min(new_min_diff, diff)
            new_max_diff = max(new_max_diff, diff)

        if new_min_diff == new_max_diff:
            return i + 1

    return -1

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    b = list(map(int, data[1:]))

    result = find_index_to_remove(n, b)
    print(result)

